async function archiveSnapshot(reason){await save();await db.put('history',{id:uuid(),record:clone(current),at:now(),reason});}
async function transcribeOne(r,note){if(transcribing.has(note.id))return;transcribing.add(note.id);try{await media.transcribe(note,settings,sessionToken);await save(r);toast('Transcription disponible, à vérifier.');}catch(err){note.transcriptionError=err.message;await save(r);throw err;}finally{transcribing.delete(note.id);}}
let queueRunning=false;
async function queueTranscriptions(){if(queueRunning||!settings?.autoTranscribe||!settings.transcriptionUrl||!navigator.onLine||recording)return;queueRunning=true;try{await save();const all=await db.getAll();for(const stored of all){const r=current?.id===stored.id?current:stored;for(const note of mediaRefs(r).filter(m=>m.kind==='audio'&&m.transcriptStatus==='pending'&&!['recording','empty'].includes(m.recordingState))){try{await transcribeOne(r,note);}catch(e){toast(e.message);return;}}}if(route==='form'&&!recording)await render();}finally{queueRunning=false;}}
$('#emergency-export').onclick=async()=>{try{await exportBackup([...unsavedRecords.values()]);toast('Copie des modifications en mémoire préparée.');}catch(e){report(e);}};
$('#retry-save').onclick=async()=>{try{for(const r of [...unsavedRecords.values()])await save(r);toast('Enregistrement réussi.');}catch(e){report(e);}};
$('#close-media').onclick=()=>$('#media-dialog').close();
$('#stop-audio').onclick=async()=>{try{await media.stopRecording();}catch(e){report(e);}};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;if(route==='settings')render().catch(report);});
window.addEventListener('hashchange',async()=>{const next=location.hash.slice(1)||'home';if(next===route)return;try{await navigate(next);}catch(e){report(e);}});
window.addEventListener('beforeunload',e=>{if(dirty||recording){e.preventDefault();e.returnValue='';}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')save().catch(report);});
function networkStatus(){$('#network').textContent=navigator.onLine?'En ligne':'Hors connexion';$('#network').classList.toggle('offline',!navigator.onLine);}
window.addEventListener('online',()=>{networkStatus();queueTranscriptions().catch(report);});window.addEventListener('offline',networkStatus);
window.addEventListener('databaseversionchange',()=>{app.innerHTML='<section class="card"><h1>Mise à jour de la base locale</h1><p>Fermez cet onglet, puis rouvrez l’application.</p></section>';});
async function serviceWorker(){if(!('serviceWorker' in navigator))return;const reg=await navigator.serviceWorker.register('./sw.js?v=1.7.0',{updateViaCache:'none'});const ready=()=>{if(reg.waiting&&navigator.serviceWorker.controller)$('#update-banner').hidden=false;};ready();reg.addEventListener('updatefound',()=>{reg.installing?.addEventListener('statechange',ready);});$('#apply-update').onclick=async()=>{if(recording){toast('Arrêter la note vocale avant la mise à jour.');return;}try{await save();reg.waiting?.postMessage({type:'ACTIVATE'});}catch(e){report(e);}};let reload=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!reload){reload=true;location.reload();}});await reg.update();}
async function acquireLock(){if(!navigator.locks)return true;return new Promise(resolve=>{navigator.locks.request('novec-survey-editor',{ifAvailable:true},async lock=>{if(!lock){resolve(false);return;}resolve(true);await new Promise(r=>lockHold=r);}).catch(()=>resolve(false));});}
async function boot(){try{networkStatus();if(!await acquireLock()){app.innerHTML='<section class="card"><h1>NOVEC Survey est déjà ouvert</h1><p>Fermez l’autre onglet de cette application, puis actualisez cette page pour protéger les modifications en cours.</p></section>';return;}
  const res=await fetch('./data/localities.json');if(!res.ok)throw Error('Référentiel localités indisponible. Ouvrez l’application avec Internet une première fois.');catalog=await res.json();await db.openDB();settings=await db.getSettings();if(settings.lastProvince&&!catalog.provinces.some(p=>p.name===settings.lastProvince)){const aliases={'Mdiq - Fnidq':"M'diq-Fnideq",'Kenitra':'Kénitra'};settings.lastProvince=aliases[settings.lastProvince]||settings.lastProvince;}const migrated=await db.migrateAll(catalog,migrateRecord);await db.simplifyCodes();records=await db.getAll();const recovered=await media.recoverAudio(records,db.saveRecord);const last=(await db.get('meta','lastRecord'))?.value;if(last)current=await db.get('localities',last);route=['home','form','exports','settings','history'].includes(location.hash.slice(1))?location.hash.slice(1):'home';await render();if(migrated)toast(`${migrated} ancienne(s) fiche(s) reprise(s). Les données originales sont conservées dans les archives.`);else if(recovered)toast('Une note vocale interrompue a été récupérée. Réécoutez-la.');serviceWorker().catch(e=>toast('Mode hors connexion non préparé : '+e.message));queueTranscriptions().catch(report);
  }catch(e){console.error(e);app.innerHTML=`<section class="card"><h1>Ouverture impossible</h1><p>${esc(e.message)}</p><p>Ne supprimez pas les données du site. Fermez les autres onglets et réessayez.</p><button class="button" onclick="location.reload()">Réessayer</button></section>`;}}
boot();
